// Catches anything the main workflow didn't handle itself and leaves a note in _failed/.
const FAIL_DIR = '/path/to/your/Obsidian Vault/Raw notes/_failed';
const TZ = 'Asia/Dhaka';
const e = $input.first().json;
const now = DateTime.now().setZone(TZ);
const fileName = `${now.toFormat('yyyy-MM-dd HHmmss')} workflow error.md`;
const err = (e.execution && e.execution.error) || {};
const text = [
  '---',
  'type: failed-capture',
  'status: needs-retry',
  `first_captured: ${now.toFormat("yyyy-MM-dd'T'HH:mm")}`,
  '---',
  '',
  `# Workflow error: ${e.workflow ? e.workflow.name : 'unknown workflow'}`,
  '',
  `**Error:** ${err.message || 'unknown'}`,
  `**Failed node:** ${(e.execution && e.execution.lastNodeExecuted) || '?'}`,
  `**Execution:** ${(e.execution && e.execution.url) || (e.execution && e.execution.id) || '?'}`,
  '',
  'The email that triggered this run has already been marked as read. Open the execution in n8n to see which one it was, then send it again.',
  '',
  '```',
  String(err.stack || '').split('\n').slice(0, 15).join('\n'),
  '```',
  '',
].join('\n');
return [{
  json: { path: `${FAIL_DIR}/${fileName}` },
  binary: { data: { data: Buffer.from(text, 'utf8').toString('base64'), mimeType: 'text/markdown', fileName, fileExtension: 'md' } },
}];
